const StudioManufacturingTools=(()=>{
 function open(records,onRepair){
  const projectId=current.id,options=records.map((r,i)=>`<option value="${i}">${esc(r.name)}</option>`).join(''),input=(id,label,value)=>`<label>${label}<input id="${id}" type="number" step="any" value="${value}"></label>`;
  modal('Manufacturing review tools',`<p>Review assembled world geometry in millimetres. Limits and process assumptions below are explicit; a passing screen does not certify a part.</p><label>Part A<select id="reviewPartA">${options}</select></label><label>Part B<select id="reviewPartB">${options}</select></label><div class="solidBaseFields">${input('processClearance','Required surface clearance mm',.2)}${input('processWall','Required sampled wall mm',1)}${input('repairTolerance','Repair weld tolerance mm',.00001)}</div><button type="button" id="reviewClearance">Check triangle clearance</button><button type="button" id="reviewWall">Sample wall thickness</button><button type="button" id="reviewRepair">Preview conservative mesh repair</button><button type="button" id="applyMeshRepair" disabled>Add repaired copy</button><pre id="manufacturingResult" role="status"></pre><p class="tiny">Clearance uses triangle distances plus a closed-shell containment screen, at most 300,000 triangle pairs. Thin walls use up to 96 inward face-centre rays; missed local details remain possible. Repair welds, removes duplicates/degenerates and orients connected faces. It does not fill holes or fix intersections. The original part is preserved.</p><details open><summary>Shaft / hole tolerance stack</summary><div class="solidBaseFields">${input('fitShaft','Shaft nominal diameter mm',10)}${input('fitShaftTolerance','Shaft ± tolerance mm',.02)}${input('fitHole','Hole nominal diameter mm',10.2)}${input('fitHoleTolerance','Hole ± tolerance mm',.05)}</div><button type="button" id="reviewFit">Calculate worst-case fit</button><p id="fitResult" role="status"></p></details><label>Material evidence / process notes<textarea id="manufacturingNotes" maxlength="4000" placeholder="Alloy grade, temper, source certificate, build orientation, process, tolerances and test evidence"></textarea></label><button type="button" id="exportManufacturingReview">Export review & assumptions</button><details><summary>CAD / slicer and physical acceptance kit</summary><p>Import the reference coupon in your chosen CAD/slicer with millimetres and Z up. Confirm 30 × 20 × 5 mm bounds and the 6 mm through-hole, inspect layer/toolpath continuity, then record machine, material and measured part dimensions in the acceptance JSON. Choose process tolerances before fabrication. These files do not claim an external software or physical pass.</p><a href="validation/coupon.stl" download>Download reference coupon STL</a> · <a href="validation/coupon-acceptance.json" download>Download acceptance record</a> · <a href="validation/README.txt" download>Acceptance steps</a></details><p id="manufacturingError" role="alert"></p>`,()=>false);
  document.getElementById('dialog').classList.add('toolsDialog');
  const $=id=>document.getElementById(id),get=()=>records[Number($('reviewPartA').value)];let repaired=null,report={created:new Date().toISOString(),projectId,certified:false,checks:[]};
  $('reviewPartB').value=String(Math.min(1,records.length-1));document.querySelector('#modalForm>button[type=submit]').textContent='Close review';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();$('dialog').close();};
  const dialog=$('dialog'),resultNode=$('manufacturingResult');let closed=false,busy=false,cancelJob=null;
  const active=()=>!closed&&dialog.open&&current.id===projectId&&$('manufacturingResult')===resultNode;
  dialog.addEventListener('close',()=>{closed=true;cancelJob?.();dialog.classList.remove('toolsDialog');},{once:true});
  function workerCheck(operation,a,b,tolerance){
   if(typeof Worker==='undefined')throw Error('Background workers are unavailable. Enable them to run manufacturing checks.');
   return new Promise((resolve,reject)=>{
    const worker=new Worker('manufacturing-worker.js?v=15.5');let finished=false;
    const finish=(error,result)=>{if(finished)return;finished=true;clearTimeout(timer);worker.terminate();cancelJob=null;error?reject(Error(error)):active()?resolve(result):reject(Error('Review closed or project changed. Reopen review.'));};
    const timer=setTimeout(()=>finish('Manufacturing check exceeded 20 seconds. Simplify the selected parts and retry.'),20000);
    cancelJob=()=>finish('Manufacturing check canceled.');
    worker.onmessage=({data})=>finish(data.error,data.result);
    worker.onerror=()=>finish('The manufacturing worker could not run. Reload and retry.');
    worker.onmessageerror=()=>finish('The manufacturing result could not be read.');
    try{worker.postMessage({operation,a,b,tolerance});}catch(e){finish(e.message);}
   });
  }
  const controls=['reviewClearance','reviewWall','reviewRepair','reviewFit','reviewPartA','reviewPartB'];
  const run=async fn=>{
   if(busy||!active())return;
   busy=true;controls.forEach(id=>$(id).disabled=true);$('applyMeshRepair').disabled=true;
   $('manufacturingError').textContent='';resultNode.textContent='Working in the background… You can close this review to cancel.';
   try{const result=await fn();if(active()){report.checks.push(result);resultNode.textContent=JSON.stringify(result,null,2);}}
   catch(e){if(active()){$('manufacturingError').textContent=e.message;resultNode.textContent='Check did not complete. No result was recorded.';}}
   finally{busy=false;if(active()){controls.forEach(id=>$(id).disabled=false);$('applyMeshRepair').disabled=!repaired;}}
  };
  const required=id=>{const n=Number($(id).value);if(!Number.isFinite(n)||n<0||n>1000)throw Error('Enter a process limit between 0 and 1000 mm.');return n;};
  $('reviewClearance').onclick=()=>run(async()=>{const a=get(),b=records[Number($('reviewPartB').value)];if(a===b)throw Error('Choose two different parts.');const requiredMm=required('processClearance'),result=await workerCheck('clearance',a.positions,b.positions);return {check:'triangle clearance',parts:[a.name,b.name],requiredMm,...result,meetsEnteredLimit:result.solidClearanceMm>=requiredMm&&result.relation==='separate closed shells'};});
  $('reviewWall').onclick=()=>run(async()=>{const a=get(),minimumMm=required('processWall'),result=await workerCheck('wall',a.positions);return {check:'sampled wall thickness',part:a.name,minimumMm,...result,belowEnteredLimit:result.sampledMinimumMm!==null&&result.sampledMinimumMm<minimumMm};});
  $('reviewRepair').onclick=()=>{repaired=null;$('applyMeshRepair').disabled=true;run(async()=>{const a=get();if(a.positions.length>54000)throw Error('Repair copies support at most 6,000 triangles. Simplify this part first.');const result=await workerCheck('repair',a.positions,undefined,Number($('repairTolerance').value)),p=result.positions,min=[0,1,2].map(k=>Math.min(...p.filter((_,i)=>i%3===k))),max=[0,1,2].map(k=>Math.max(...p.filter((_,i)=>i%3===k))),origin=[(min[0]+max[0])/2,min[1],(min[2]+max[2])/2],mesh={version:1,positions:p.map((v,i)=>+(v-origin[i%3]).toFixed(6))};if(!StudioMeshParts.validate(mesh))throw Error('Repaired copy exceeds portable part limits, or still contains invalid triangles.');repaired={mesh,name:(a.name+' repaired').slice(0,80),material:a.material};$('applyMeshRepair').disabled=false;const {positions,...summary}=result;return {check:'conservative repair preview',part:a.name,...summary};});};
  $('reviewPartA').onchange=()=>{repaired=null;$('applyMeshRepair').disabled=true;};
  $('applyMeshRepair').onclick=async()=>{try{if(!repaired)throw Error('Preview a repair first.');if(current.id!==projectId)throw Error('Project changed. Reopen review.');$('applyMeshRepair').disabled=true;await onRepair(repaired);$('dialog').close();toast('Repaired mesh added as a separate copy. Original retained; undo is available.');}catch(e){$('manufacturingError').textContent=e.message;$('applyMeshRepair').disabled=!repaired;}};
  $('reviewFit').onclick=()=>run(()=>{const result=StudioManufacturing.fit({shaftMm:Number($('fitShaft').value),shaftToleranceMm:Number($('fitShaftTolerance').value),holeMm:Number($('fitHole').value),holeToleranceMm:Number($('fitHoleTolerance').value)});$('fitResult').textContent=`${result.fit}: ${result.minimumDiametralClearanceMm.toFixed(4)} to ${result.maximumDiametralClearanceMm.toFixed(4)} mm diametral clearance`;return {check:'worst-case tolerance stack',...result};});
  $('exportManufacturingReview').onclick=()=>download('manufacturing-review.json',JSON.stringify({...report,materialProcessNotes:$('manufacturingNotes').value,externalCadReviewed:false,physicalPartTested:false},null,2),'application/json');
 }
 return {open};
})();
